{"code": "def stochastic(d, buy, n=14, sell=80):
    k = (d.close - d.low.rolling(n).min()) / (d.high.rolling(n).max() - d.low.rolling(n).min()) * 100
    state, out = 0.0, []
    for v in k:
        if v < buy:
            state = 1.0
        elif v > sell:
            state = 0.0
        out.append(state)
    return pd.Series(out, index=d.index)

